    c,
    reply: reply,
    snapshot: snapshot,
    openAsks: openAsks,
    fail: fail,
  );
  if (transfer.failed) return false;
  final verdict = _handOverVerdict(
    c,
    reply: reply,
    snapshot: snapshot,
    view: armed.view,
    range: armed.range,
  );
