/// A text responder that records which MODEL ids it served; a merged
/// hand-over call (GOAL #2394) gets a valid transfer built from its own
/// instruction instead of the bare text.
StreamFunction _recordingText(List<String> seen, String text) {
  return (model, context, {cancelToken}) {
    final stream = AssistantMessageEventStream();
    seen.add(model.id);
    final reply = isHandOverCall(context)
        ? handOverReplyFor(context, text: text)
        : text;
    stream.push(
      DoneEvent(
        reason: StopReason.stop,
        message: AssistantMessage(
          content: [TextContent(text: reply)],
          api: model.api,
          provider: model.provider,
          model: model.id,
          usage: Usage.zero,
          stopReason: StopReason.stop,
          timestamp: DateTime.now(),
        ),
      ),
    );
    stream.end();
    return stream;
  };
}

/// Errors every summarization-shaped call (structured judge, structured
/// checkpoint, classic summary); answers ordinary turns with [text].
StreamFunction _failingSummarizer(List<String> seen, String text) {
  bool isSummarization(Context context) =>
      context.systemPrompt == summarizationSystemPrompt ||
      context.systemPrompt == hideJudgeSystemPrompt ||
      context.systemPrompt == structuredCheckpointPrompt;
  return (model, context, {cancelToken}) {
    final stream = AssistantMessageEventStream();
    seen.add(model.id);
    if (isSummarization(context)) {
      stream.push(
        DoneEvent(
          reason: StopReason.error,
          message: AssistantMessage(
            content: const [],
            api: model.api,
            provider: model.provider,
            model: model.id,
            usage: Usage.zero,
            stopReason: StopReason.error,
            errorMessage: 'summary backend down',
            timestamp: DateTime.now(),
          ),
        ),
      );
    } else {
      stream.push(
        DoneEvent(
          reason: StopReason.stop,
          message: AssistantMessage(
            content: [TextContent(text: text)],
            api: model.api,
            provider: model.provider,
            model: model.id,
            usage: Usage.zero,
            stopReason: StopReason.stop,
            timestamp: DateTime.now(),
          ),
        ),
      );
    }
    stream.end();
    return stream;
  };
}

Agent _agent(
  StreamFunction stream, {
  int contextWindow = 512,
  String systemPrompt = '',
  List<AgentTool> tools = const [],
}) {
  return Agent(
    model: Model(
      id: 'main-model',
      name: 'main-model',
      api: 'anthropic-messages',
      provider: 'anthropic',
      baseUrl: 'https://main.invalid',
      contextWindow: contextWindow,

      contextWindow: contextWindow,
      maxTokens: 4096,
      input: const ['text'],
    ),
    systemPrompt: systemPrompt,
    streamFunction: stream,
    toolRegistry: ToolRegistry(tools),
  );
}

